sp_widget.client_script:
api.controller = function($scope, spUtil, $location, spAriaFocusManager) {
    /* global document, console */

    //action on the data table widget
    $scope.$on('data_table.click', function(e, parms) {
        var pageId = $scope.data.page_id || 'form'; //hoc_hira_rl_form
			console.log('-------------------------------------\r\n' + JSON.stringify(parms) + '\r\n-------------------------------------')

        var s = {
            id: pageId,
            table: parms.table,
            sys_id: parms.sys_id,
            view: parms.view || 'sp',
            parent_field: $scope.data.parentFieldName,
            parent: $scope.data.parent_id
        };

        var newURL = $location.search(s); //takes the object to create a URL

        spAriaFocusManager.navigateToLink(newURL.url());
    });

    //OHS scope / widget customization
    $scope.newRecord = function() {
        var parms = {
            id: $scope.data.page_id || 'form', //hoc_hira_rl_form,
            table: $scope.data.table,
            view: $scope.data.view || 'sp',
            sys_id: '-1',
            parent_field: $scope.data.parentFieldName,
            parent: $scope.data.parent_id,
            query:$scope.data.parentFieldName+"="+$scope.data.parent_id
        };

        /*if ($scope.data.exportQuery != '') {
            parms.query = $scope.data.exportQuery;
        }*/

        $location.search(parms);
    };
}

sp_widget.css:
.panel-heading { padding-left: 8px; } 

thead { border-bottom: 1px solid #ddd; } 

table { margin-bottom: 0; border-collapse: separate; }

.table > thead > tr > th {
	border-right: 1px solid #ddd;
	border-bottom: none;
	cursor: pointer; 
	vertical-align: middle; 

	&:nth-child(2) { border-left: none; } 

	&:last-child { border-right: none; } 
}

th i { display: inline-block; margin-left: 5px; color: #A0A0A0; } 

div.data-table-high-contrast 

th i { color: $gray; } th

.disabled{ color:#ddd; }

.th-title { display: inline-block; color: $primary; }

.panel-body { overflow: auto; padding: 0px; }

.selected { color: #fff; background-color: $data-table-selected; border-color: 1px solid #fff; }

.table-striped td.selected a:not(.text-muted):not(.btn) { color: $sp-tagline-color; } 

tbody tr:last-child { border-bottom: none; }

.pruned-msg { padding-bottom: 10px; padding-left: 4px; text-align: center; }

.pruned-msg-filter-pad { padding-top:8px; }

.filter-breadcrumbs { padding-top: 3px; }

.filter-breadcrumbs ~

.table { border-top: 1px solid #ddd; }

.dropdown-toggle { background: none; padding: 0 0 4px 0; }

.sp-list-cell { white-space: pre-wrap; }

.user_image { max-width:100px; max-height:100px; }

sp_widget.script:
/* global input, data, $sp, options */
(function() {
    /*  "use strict"; - linter issues */
    // populate the 'data' object
    var sp_page = $sp.getValue('sp_page');
    var pageGR = new GlideRecord('sp_page');

    //gs.debug('HOC OHSM widget - sp_page: ' + sp_page); //hoc_hira_rl_form
    //gs.debug('HOC OHSM widget - data - start: ' + JSON.stringify(data));

    pageGR.get(sp_page);
    data.page_id = pageGR.getValue("id");



    $sp.getValues(data);
    if (data.field_list) {
        data.fields_array = data.field_list.split(',');
    } else {
        data.field_list = $sp.getListColumns(data.table);
    }

    if (input) {
        data.p = input.p;
        data.o = input.o;
        data.d = input.d;
        data.q = input.q;
        // additional inputs for using a spModal
        data.table = input.table;
        data.filter = input.filter;
        data.view = input.view;
    }
    data.p = data.p || 1;
    data.o = data.o || $sp.getValue('order_by');
    data.d = data.d || $sp.getValue('order_direction');

    data.page_index = (data.p - 1);
    data.window_size = $sp.getValue('maximum_entries') || 10;
    data.window_start = (data.page_index * data.window_size);
    data.window_end = (((data.page_index + 1) * data.window_size));
    // adding data.filter here so 
    // it can be picked up from an input.filter above
    data.filter = data.filter || $sp.getValue("filter");

    var gr = new GlideRecordSecure(data.table);
    var table = $sp.getParameter("table");


    data.parent_id = $sp.getParameter("sys_id");
    if (table === 'x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment') {
        data.parentFieldName = 'parent_hazard';
    } else if (table === 'x_hccc_hoc_ohs_hira_case') {
        data.parentFieldName = 'hira_case';
    }


    if (!gr.isValid()) {
        data.invalid_table = true;
        data.table_label = data.table;
        return;
    }
    data.table_label = gr.getLabel();

		////////////////////////////////////
		// NEW BUTTON
		data.show_new = true;
		data.canCreate = gr.canCreate();
		data.newButtonUnsupported = data.table == "sys_attachment";
		////////////////////////////////////

    var params = {};

    params.table = data.table;
    params.fields = data.field_list;
    params.o = data.o;
    params.d = data.d;
    //params.filter = data.filter;
    params.filter = data.parentFieldName + '=' + $sp.getParameter("sys_id");
    params.window_size = data.window_size;
    params.view = data.view || 'sp';
    params.useInstanceTitle = true; // to make sure Data Table widget uses headerTitle always
    params.headerTitle = options.title;
    params.show_breadcrumbs = false; //we don't want to show the filter
    params.show_new = false;
    params.hide_header = true;

    gs.debug('HoC OHSM Related List - Params: ' + JSON.stringify(params));

    if (data.parentFieldName) { //not initializing widget if there's no table/parent field
        data.dataTableWidget = $sp.getWidget('widget-data-table', params);
        //data.dataTableWidget = $sp.getWidget('hoc_ohsm_data_table', params);
    }

})();
